CREATE TABLE projects (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(255) NOT NULL UNIQUE, start_date DATE, end_date DATE, status VARCHAR(255), description VARCHAR(255));
CREATE TABLE tasks (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, title VARCHAR(255) NOT NULL, estimate_hours INTEGER, assignee VARCHAR(255), status ENUM('COMPLETED', 'DONE', 'IN_PROGRESS', 'TODO'), finished_at TIMESTAMP, created_at TIMESTAMP, project_id BIGINT NOT NULL REFERENCES projects(id));
